WITH base AS (SELECT id, session_id, event_type, page, event_time, duration_sec, UPPER(event_type) AS event_type_upper FROM web_events WHERE page IS DISTINCT FROM '/home'), with_gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS new_group_flag FROM base), sessions_web_events AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id_2 FROM with_gaps) SELECT CASE WHEN duration_sec >= 500 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, ROUND(SUM(new_group_flag) / NULLIF(COUNT(CASE WHEN event_type = 'purchase' THEN 1 END), 0), 2) AS new_group_flag_per_purchase, COUNT(DISTINCT page) AS distinct_pages, BIT_OR(duration_sec) AS duration_sec_bit_or FROM sessions_web_events GROUP BY duration_sec_tier HAVING COUNT(DISTINCT page) < 1000 ORDER BY duration_sec_bit_or DESC;
